export interface Careers01Role {
  id: string;
  title: string;
  department: string;
  location: string;
  commitment: string;
  description: string;
  href?: string;
}
export interface Careers01Principle {
  id: string;
  title: string;
  description: string;
}
export interface Careers01Step {
  id: string;
  title: string;
  description: string;
}
export interface Careers01Props {
  company?: string;
  logoSrc?: string;
  eyebrow?: string;
  title?: string;
  description?: string;
  introTitle?: string;
  introDescription?: string;
  roles?: readonly Careers01Role[];
  principles?: readonly Careers01Principle[];
  steps?: readonly Careers01Step[];
  companyHref?: string;
  notice?: string;
}
export interface Careers01Filters {
  query: string;
  department: string;
  location: string;
}
