export const sampleSteps: readonly Careers01Step[] = [
  {
    id: "hello",
    title: "Start with a conversation.",
    description:
      "Tell us about the work you enjoy and what you would like to do next.",
  },
  {
    id: "work",
    title: "Show us how you think.",
    description:
      "Talk through a piece of work, the decisions behind it, and what you learned.",
  },
  {
    id: "people",
    title: "Meet the people.",
    description:
      "Make space for questions in both directions before deciding what comes next.",
  },
];
export function careersOptions(roles: readonly Careers01Role[]) {
  return {
    departments: [...new Set(roles.map((role) => role.department))],
    locations: [...new Set(roles.map((role) => role.location))],
  };
}
export function normalizeCareersFilters(
  roles: readonly Careers01Role[],
  filters: Careers01Filters,
) {
  const options = careersOptions(roles);
  return {
    ...filters,
    department: options.departments.includes(filters.department)
      ? filters.department
      : "all",
    location: options.locations.includes(filters.location)
      ? filters.location
      : "all",
  };
}
export function filterCareersRoles(
  roles: readonly Careers01Role[],
  filters: Careers01Filters,
) {
  const active = normalizeCareersFilters(roles, filters);
  const terms = active.query
    .trim()
    .toLocaleLowerCase("en-GB")
    .split(/\s+/)
    .filter(Boolean);
  return roles.filter(
    (role) =>
      (active.department === "all" || role.department === active.department) &&
      (active.location === "all" || role.location === active.location) &&
      terms.every((term) =>
        `${role.title} ${role.department} ${role.location} ${role.commitment} ${role.description}`
          .toLocaleLowerCase("en-GB")
          .includes(term),
      ),
  );
}
export function groupCareersRoles(roles: readonly Careers01Role[]) {
  return careersOptions(roles).departments.map((department) => ({
    department,
    roles: roles.filter((role) => role.department === department),
  }));
}
export function validateCareers(
  roles: readonly Careers01Role[],
  principles: readonly Careers01Principle[] = [],
  steps: readonly Careers01Step[] = [],
) {
  for (const items of [roles, principles, steps]) {
    const ids = new Set<string>();
    for (const item of items) {
      if (!/^[a-zA-Z0-9][a-zA-Z0-9_-]*$/.test(item.id) || ids.has(item.id))
        throw new RangeError("Careers items require unique anchor-safe IDs.");
      ids.add(item.id);
    }
  }
}

.careers01 {
  --careers01-column-gap: var(--space-10);
  --careers01-aside-width: 32%;
  padding: var(--space-5) var(--container-padding-lg) var(--space-8);
  background: var(--background-primary);
  color: var(--text-primary);
  font-family: var(--font-family-body);
}
.careers01 *,
.careers01 *::before,
.careers01 *::after {
  box-sizing: border-box;
}
.careers01 :is(h1, h2, h3, h4, p, ol, dl, dd) {
  margin: 0;
}
.careers01-inner {
  max-width: var(--container-max-width);
  margin-inline: auto;
}
.careers01 a {
  color: inherit;
  text-underline-offset: var(--space-1);
}
.careers01 a:focus-visible {
  outline: var(--focus-ring-width) solid var(--focus-ring-color);
  outline-offset: var(--focus-ring-offset);
}
.careers01 :is(header, section) {
  scroll-margin-block-start: var(--space-7);
}
.careers01 .careers01-masthead {
  gap: var(--space-5);
  padding-block-end: var(--space-5);
}
.careers01-brand {
  display: flex;
  gap: var(--space-3);
  align-items: center;
  font-size: var(--font-size-xl);
  font-weight: var(--font-weight-semibold);
  text-decoration: none;
}
.careers01-brand .media {
  width: var(--space-9);
}
.careers01-brand > span {
  font-size: var(--typography-micro-size);
  letter-spacing: var(--letter-spacing-wide);
  color: var(--text-muted);
  font-weight: var(--font-weight-regular);
}
.careers01-masthead nav {
  font-size: var(--typography-caption-size);
}
.careers01-masthead nav a {
  text-decoration: none;
}
.careers01-masthead nav a:hover {
  text-decoration: underline;
}
.careers01-hero {
  background: var(--brand-primary-muted);
  border: var(--border-width-thin) solid var(--border-default);
  border-radius: var(--section-radius);
  padding: var(--space-7);
}
.careers01 .careers01-kicker {
  font-size: var(--typography-micro-size);
  line-height: var(--line-height-relaxed);
  letter-spacing: var(--letter-spacing-wider);
  font-weight: var(--font-weight-semibold);
  color: var(--text-muted);
}
.careers01 .careers01-hero-body {
  gap: var(--space-8);
  padding-block: var(--space-7);
}
.careers01-hero-body > div {
  flex: 1 1 75%;
  min-width: 0;
}
.careers01-hero h1 {
  font-size: var(--typography-hero-size);
  letter-spacing: var(--letter-spacing-tighter);
  line-height: var(--line-height-tight);
  white-space: pre-line;
}
.careers01-hero-body > div > p {
  margin-block-start: var(--space-6);
  max-width: var(--content-width-narrow);
  font-size: var(--typography-lead-size);
  line-height: var(--typography-lead-lineheight);
}
.careers01-role-count {
  flex: 0 1 20%;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
  text-decoration: none;
  border-block-start: var(--border-width-strong) solid var(--brand-primary);
  padding-block-start: var(--space-4);
}
.careers01-role-count > strong {
  font-size: calc(var(--font-size-6xl) * 1.5);
  line-height: var(--line-height-none);
  letter-spacing: var(--letter-spacing-tighter);
  font-family: var(--font-family-display);
}
.careers01-role-count > span {
  font-size: var(--font-size-sm);
}
.careers01 .careers01-hero-footer {
  gap: var(--space-4);
  border-block-start: var(--border-width-thin) solid var(--border-default);
  padding-block-start: var(--space-4);
  font-size: var(--typography-micro-size);
  letter-spacing: var(--letter-spacing-wide);
}
.careers01-board {
  padding-block: var(--space-12);
}
.careers01 .careers01-board-layout {
  gap: var(--careers01-column-gap);
}
.careers01-board-intro {
  flex: 0 0 var(--careers01-aside-width);
  min-width: 0;
  position: sticky;
  top: var(--space-7);
}
.careers01-board-intro h2 {
  font-size: var(--font-size-3xl);
  letter-spacing: var(--typography-heading-letterspacing);
  line-height: var(--line-height-tight);
  margin-block: var(--space-4) var(--space-5);
}
.careers01-board-intro > p:last-of-type {
  font-size: var(--font-size-sm);
  line-height: var(--line-height-relaxed);
}
.careers01-at-a-glance {
  border-block-start: var(--border-width-thin) solid var(--border-default);
  margin-block-start: var(--space-7);
}
.careers01-at-a-glance > div {
  display: flex;
  justify-content: space-between;
  gap: var(--space-4);
  padding-block: var(--space-3);
  border-block-end: var(--border-width-thin) solid var(--border-default);
  font-size: var(--typography-caption-size);
}
.careers01-at-a-glance dt {
  color: var(--text-muted);
}
.careers01-at-a-glance dd {
  font-variant-numeric: tabular-nums;
}
.careers01-role-board {
  flex: 1 1 0;
  min-width: 0;
}
.careers01-filter-bar {
  padding: var(--space-5);
  background: var(--surface-base);
  border-radius: var(--card-radius);
}
.careers01-filter-bar label {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
  font-size: var(--typography-caption-size);
}
.careers01-filter-bar .input,
.careers01-filter-bar .select {
  width: 100%;
}
.careers01 .careers01-filter-row {
  margin-block-start: var(--space-4);
  gap: var(--space-4);
}
.careers01-filter-row > label {
  flex: 1 1 40%;
  min-width: 0;
}
.careers01 .careers01-results-header {
  gap: var(--space-3);
  min-height: var(--button-min-height);
  margin-block: var(--space-5);
  font-size: var(--typography-caption-size);
  color: var(--text-muted);
}
.careers01-department + .careers01-department {
  margin-block-start: var(--space-7);
}
.careers01 .careers01-department-heading {
  gap: var(--space-4);
  border-block-end: var(--border-width-strong) solid var(--border-strong);
  padding-block-end: var(--space-4);
}
.careers01-department-heading h3 {
  font-size: var(--font-size-sm);
  letter-spacing: var(--letter-spacing-wide);
}
.careers01-department-heading > span {
  font-size: var(--typography-caption-size);
  color: var(--text-muted);
}
.careers01-role {
  padding-block: var(--space-5);
  border-block-end: var(--border-width-thin) solid var(--border-default);
}
.careers01 .careers01-role-heading {
  gap: var(--space-3);
}
.careers01-role h4 {
  font-size: var(--font-size-xl);
  line-height: var(--line-height-snug);
  letter-spacing: var(--letter-spacing-tight);
}
.careers01-role h4 a {
  text-decoration: none;
}
.careers01-role h4 a:hover {
  text-decoration: underline;
}
.careers01-role > p {
  margin-block-start: var(--space-3);
  font-size: var(--font-size-sm);
  line-height: var(--line-height-relaxed);
}
.careers01 .careers01-role-meta {
  margin-block-start: var(--space-4);
  gap: var(--space-4);
  font-size: var(--typography-caption-size);
  color: var(--text-muted);
}
.careers01-empty {
  padding: var(--space-7);
  border: var(--border-width-thin) solid var(--border-default);
  border-radius: var(--card-radius);
}
.careers01-empty h3 {
  font-size: var(--font-size-xl);
  margin-block-end: var(--space-3);
}
.careers01-empty > p {
  font-size: var(--font-size-sm);
  line-height: var(--line-height-relaxed);
}
.careers01-empty .btn {
  margin-block-start: var(--space-5);
}
.careers01-principles {
  padding-block: var(--space-8) var(--space-12);
  border-block-start: var(--border-width-thin) solid var(--border-default);
}
.careers01 .careers01-section-heading {
  gap: var(--space-5);
  margin-block-end: var(--space-7);
}
.careers01-section-heading h2,
.careers01-process h2 {
  font-size: var(--website-title-size);
  line-height: var(--line-height-tight);
  letter-spacing: var(--letter-spacing-tighter);
  margin-block-start: var(--space-3);
}
.careers01-section-heading > p {
  font-size: var(--typography-caption-size);
}
.careers01 .careers01-principle-list {
  gap: var(--space-6);
}
.careers01-principle-list > div {
  flex: 0 1 calc((100% - var(--space-6) * 2) / 3);
  min-width: 0;
  border-block-start: var(--border-width-thin) solid var(--border-default);
  padding-block-start: var(--space-5);
}
.careers01-index {
  display: block;
  font-size: var(--font-size-2xl);
  color: var(--text-muted);
  letter-spacing: var(--letter-spacing-tight);
}
.careers01-principle-list h3 {
  margin-block: var(--space-5) var(--space-4);
  font-size: var(--font-size-xl);
  line-height: var(--line-height-snug);
}
.careers01-principle-list p {
  font-size: var(--font-size-sm);
  line-height: var(--line-height-relaxed);
}
.careers01-process {
  display: flex;
  gap: var(--careers01-column-gap);
  padding: var(--space-7);
  background: var(--surface-base);
  border-radius: var(--card-radius);
}
.careers01-process > div {
  flex: 1 1 40%;
  min-width: 0;
}
.careers01-process ol {
  flex: 1 1 60%;
  min-width: 0;
  list-style: none;
  padding: 0;
}
.careers01-process li {
  display: flex;
  gap: var(--space-5);
}
.careers01-process li + li {
  margin-block-start: var(--space-5);
  padding-block-start: var(--space-5);
  border-block-start: var(--border-width-thin) solid var(--border-default);
}
.careers01-process h3 {
  font-size: var(--font-size-lg);
  line-height: var(--line-height-snug);
  margin-block-end: var(--space-3);
}
.careers01-process li p {
  font-size: var(--font-size-sm);
  line-height: var(--line-height-relaxed);
}
.careers01-footer {
  margin-block-start: var(--space-10);
  border-block-start: var(--border-width-thin) solid var(--border-default);
  padding-block-start: var(--space-5);
}
.careers01-footer > .flex {
  gap: var(--space-4);
  font-size: var(--typography-caption-size);
}
.careers01-footer > p {
  margin-block-start: var(--space-4);
  font-size: var(--typography-caption-size);
  line-height: var(--line-height-relaxed);
}
.careers01 :is(h1, h2, h3, h4, p, a, span, strong) {
  overflow-wrap: anywhere;
}
@media (max-width: 900px) {
  .careers01 {
    padding-inline: var(--container-padding);
  }
  .careers01 .careers01-board-layout {
    flex-direction: column;
  }
  .careers01-board-intro {
    position: static;
    flex-basis: auto;
  }
  .careers01-role-board {
    width: 100%;
  }
  .careers01-process {
    flex-direction: column;
  }
  .careers01-role-count > strong {
    font-size: var(--font-size-6xl);
  }
}
@media (max-width: 600px) {
  .careers01 {
    padding-inline: var(--space-4);
  }
  .careers01-hero,
  .careers01-process {
    padding: var(--space-5);
  }
  .careers01 .careers01-hero-body {
    flex-direction: column;
    align-items: start;
    gap: var(--space-5);
  }
  .careers01-role-count {
    flex-basis: auto;
    flex-direction: row;
    align-items: end;
    width: 100%;
    gap: var(--space-5);
  }
  .careers01-role-count > strong {
    font-size: var(--font-size-4xl);
  }
  .careers01-principle-list > div {
    flex-basis: 100%;
  }
  .careers01-filter-row > label {
    flex-basis: 100%;
  }
}
